def is_samepatterns(colors, patterns):
    """
    Check whether the colors list follows the same sequence as the patterns list.

    Args:
        colors: List of color values
        patterns: List of pattern values

    Returns:
        bool: True if colors follow the same pattern as patterns, False otherwise
    """
    if len(colors) != len(patterns):
        return False

    if len(colors) == 0:
        return True

    # Create mappings from pattern to color and color to pattern
    pattern_to_color = {}
    color_to_pattern = {}

    for i in range(len(colors)):
        pattern = patterns[i]
        color = colors[i]

        # Check if this pattern has been seen before
        if pattern in pattern_to_color:
            # If pattern was seen, it should map to the same color
            if pattern_to_color[pattern] != color:
                return False
        else:
            # New pattern, check if color was already mapped to a different pattern
            if color in color_to_pattern:
                if color_to_pattern[color] != pattern:
                    return False
            else:
                # Create new mappings
                pattern_to_color[pattern] = color
                color_to_pattern[color] = pattern

    return True
